window.__INDEX=[{"t": "Academic writing basics", "d": "How to write your own academic work — the structure, the tone, and how to use sources honestly.", "u": "/learn/academic-writing/academic-writing-basics/", "s": "Academic writing"}, {"t": "British vs American English", "d": "The main spelling, word and punctuation differences, and how to be consistent in whichever one you use.", "u": "/learn/grammar-language/british-vs-american-english/", "s": "Grammar & language"}, {"t": "Comma rules", "d": "The main uses of the comma, and the four comma mistakes that most often confuse readers.", "u": "/learn/grammar-language/comma-rules/", "s": "Grammar & language"}, {"t": "How to avoid plagiarism", "d": "Use sources honestly — quote, paraphrase and cite — and keep your work your own.", "u": "/learn/research-sources/how-to-avoid-plagiarism/", "s": "Research & sources"}, {"t": "How to overcome writer's block", "d": "Practical, non-mystical ways to get unstuck when the words will not come.", "u": "/learn/start-writing/how-to-overcome-writers-block/", "s": "Start writing"}, {"t": "How to proofread", "d": "A step-by-step method to catch typos, punctuation errors and inconsistencies before you submit or publish.", "u": "/learn/editing-proofreading/how-to-proofread/", "s": "Editing & proofreading"}, {"t": "How to revise a draft", "d": "Turn a rough first draft into a sharper, clearer piece by revising big to small.", "u": "/learn/writing-process/how-to-revise-a-draft/", "s": "Writing process"}, {"t": "How to start journaling", "d": "A low-pressure way to build a journaling habit — with prompts and ideas to keep you going.", "u": "/learn/journaling-personal/how-to-start-journaling/", "s": "Journaling & personal writing"}, {"t": "How to start writing", "d": "A beginner-friendly, step-by-step way to go from a blank page to a first finished piece — without waiting for inspiration.", "u": "/learn/start-writing/how-to-start-writing/", "s": "Start writing"}, {"t": "How to tell if your writing is good", "d": "Move past vague self-doubt with concrete, checkable criteria that show whether a piece works.", "u": "/learn/common-problems/how-to-tell-if-your-writing-is-good/", "s": "Common writing problems"}, {"t": "How to turn an idea into an outline", "d": "Convert a vague topic into a structured outline you can write a full piece from.", "u": "/learn/start-writing/how-to-turn-an-idea-into-an-outline/", "s": "Start writing"}, {"t": "How to write a blog post", "d": "A practical structure for blog posts people actually read — scannable, useful, and individual.", "u": "/learn/types-of-writing/how-to-write-a-blog-post/", "s": "Types of writing"}, {"t": "How to write a professional email", "d": "A clear, polite, high-functioning email that gets a response and reflects well on you.", "u": "/learn/professional-writing/how-to-write-a-professional-email/", "s": "Professional & work writing"}, {"t": "How to write a short story", "d": "Find a story, build characters and conflict, and shape a short piece that hits a single effect.", "u": "/learn/creative-writing/how-to-write-a-short-story/", "s": "Creative writing"}, {"t": "How to write an essay", "d": "The classic essay structure — introduction, body, conclusion — explained step by step with an example.", "u": "/learn/types-of-writing/how-to-write-an-essay/", "s": "Types of writing"}, {"t": "How to write an introduction", "d": "Open a piece so the reader knows what it is about and wants to keep reading.", "u": "/learn/structure-formatting/how-to-write-an-introduction/", "s": "Structure & formatting"}, {"t": "How to write search-friendly content", "d": "Write for readers first and search engines second, without straying into keyword stuffing.", "u": "/learn/online-writing/how-to-write-search-friendly-content/", "s": "Online & content writing"}, {"t": "Paragraph basics", "d": "The one-idea-per-paragraph rule, how to build a strong paragraph, and the mistakes that make writing feel disjointed.", "u": "/learn/writing-basics/paragraph-basics/", "s": "Writing basics"}, {"t": "Sentence basics", "d": "What a sentence needs, the four main sentence types, and the two common mistakes that break them.", "u": "/learn/writing-basics/sentence-basics/", "s": "Writing basics"}, {"t": "The writing process", "d": "The repeatable ten-stage workflow that takes an idea to a published, finished piece.", "u": "/learn/writing-process/the-writing-process/", "s": "Writing process"}, {"t": "Tone, voice and audience", "d": "How to match your writing to the person reading it, and why tone and voice are not the same thing.", "u": "/learn/writing-basics/tone-voice-audience/", "s": "Writing basics"}, {"t": "Word counter", "d": "Count words, characters and paragraphs as you type.", "u": "/tools/word-counter/", "s": "Tools"}, {"t": "Character counter", "d": "Count characters for bios, headlines and limits.", "u": "/tools/character-counter/", "s": "Tools"}, {"t": "Character counter (no spaces)", "d": "Count characters without counting spaces.", "u": "/tools/character-counter-no-spaces/", "s": "Tools"}, {"t": "Sentence counter", "d": "Count sentences and paragraphs in your text.", "u": "/tools/sentence-counter/", "s": "Tools"}, {"t": "Paragraph counter", "d": "Count paragraphs and how readable the structure is.", "u": "/tools/paragraph-counter/", "s": "Tools"}, {"t": "Reading time calculator", "d": "How long a reader takes to finish your piece.", "u": "/tools/reading-time/", "s": "Tools"}, {"t": "Word density calculator", "d": "See your most-used content words.", "u": "/tools/word-density/", "s": "Tools"}, {"t": "Case converter", "d": "Switch between UPPER, lower, Title, sentence and camelCase.", "u": "/tools/case-converter/", "s": "Tools"}, {"t": "Text cleaner", "d": "Fix extra spaces, odd line breaks and whitespace.", "u": "/tools/text-cleaner/", "s": "Tools"}, {"t": "Remove extra spaces", "d": "Collapse double spaces into single ones.", "u": "/tools/remove-extra-spaces/", "s": "Tools"}, {"t": "Line break cleaner", "d": "Remove stray blank lines and tidy breaks.", "u": "/tools/line-break-cleaner/", "s": "Tools"}, {"t": "Text sorter", "d": "Sort a list alphabetically, ascending or descending.", "u": "/tools/text-sorter/", "s": "Tools"}, {"t": "Duplicate line remover", "d": "Remove repeated lines from a list.", "u": "/tools/duplicate-line-remover/", "s": "Tools"}, {"t": "Writing timer", "d": "A simple focus timer for your next writing session.", "u": "/tools/writing-timer/", "s": "Tools"}, {"t": "Article outline generator", "d": "Generate a structure for your next article.", "u": "/tools/article-outline-generator/", "s": "Tools"}, {"t": "Writing checklist generator", "d": "Turn checklist items into a tickable box list.", "u": "/tools/writing-checklist-generator/", "s": "Tools"}, {"t": "I don't know what to write", "d": "Start from the reader's question, not your own mind. What is the one thing someone wants to understand or solve? Write d", "u": "/problems/", "s": "Problems"}, {"t": "I can't start", "d": "Shrink the first task. Do not aim to write the piece; aim to write two sentences that state the main idea. Use a timer f", "u": "/problems/", "s": "Problems"}, {"t": "My introduction is weak", "d": "Cut the general opening. Start with something specific: a fact, a moment, a short scene, or a question. Shorten the firs", "u": "/problems/", "s": "Problems"}, {"t": "My writing sounds boring", "d": "Be concrete. Replace abstract nouns and general statements with specific details, names, numbers and examples. Use activ", "u": "/problems/", "s": "Problems"}, {"t": "My paragraphs are too long", "d": "Check whether a paragraph covers more than one idea; if so, split it. Aim for a topic sentence, a few supporting sentenc", "u": "/problems/", "s": "Problems"}, {"t": "I repeat myself", "d": "Read the piece and underline every point stated more than once. Delete the weaker repetition. Use a word-density check t", "u": "/problems/", "s": "Problems"}, {"t": "My sentences are confusing", "d": "Find the subject and verb of each sentence. If they are far apart or buried, rewrite so the subject leads. Split long se", "u": "/problems/", "s": "Problems"}, {"t": "I don't know how to end", "d": "The conclusion should state what the piece established and why it matters, without new arguments. Go back to your main p", "u": "/problems/", "s": "Problems"}, {"t": "I have too many ideas", "d": "This usually means you have not chosen. Pick the single point the piece is about and write it in one sentence. Keep the ", "u": "/problems/", "s": "Problems"}, {"t": "I don't know how long my article should be", "d": "Match length to format and audience. A blog post is usually 800–1,500 words; a magazine feature can be 2,000–4,000; a ne", "u": "/problems/", "s": "Problems"}, {"t": "I don't know how to research", "d": "Define the question you need to answer. Search for reliable primary and secondary sources, prefer the original, and reco", "u": "/problems/", "s": "Problems"}, {"t": "I don't know how to cite sources", "d": "Whenever you use a fact, idea or direct quote that is not your own or common knowledge, give credit. Quote exact words w", "u": "/problems/", "s": "Problems"}, {"t": "I don't know whether my writing is good", "d": "Use criteria, not a feeling. Is it clear to a cold reader? Does it do its job? Does it hold together? Is it free of erro", "u": "/problems/", "s": "Problems"}, {"t": "I keep making grammar mistakes", "d": "Learn the few rules that cause most errors: subject-verb agreement, comma splices, run-ons, sentence fragments, homophon", "u": "/problems/", "s": "Problems"}, {"t": "I can't finish my draft", "d": "Finishing is a separate job from perfecting. Get the whole thing down in an ugly first pass, then stop and let it cool. ", "u": "/problems/", "s": "Problems"}, {"t": "My writing sounds too formal", "d": "Loosen the register. Prefer everyday words to academic ones, write to a person rather than to 'the reader', and cut unne", "u": "/problems/", "s": "Problems"}, {"t": "My writing sounds too casual", "d": "For a professional or academic context, tighten up. Remove slang, fillers and excessive exclamation marks. Replace contr", "u": "/problems/", "s": "Problems"}, {"t": "I don't know what an editor wants", "d": "Read the publication's official guidelines — they say what they accept, the length, the pay, and the rules. Then read se", "u": "/problems/", "s": "Problems"}, {"t": "Glossary: Active voice", "d": "The subject performs the action: \"The writer finished the report.\" Usually clearer and more direct than the passive voice.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Anecdote", "d": "A short, interesting story about a real person or event, used to open or illustrate a piece.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Abstract", "d": "A brief summary of a research paper that states the question, method, results and conclusion. Sometimes the only part many people read.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Adjective", "d": "A word that describes a noun: \"a clear, concise report.\"", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Adverb", "d": "A word that modifies a verb, adjective or other adverb, often ending in -ly: \"she wrote carefully.\"", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Argument", "d": "The central claim or point you are making and supporting with evidence.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Audience", "d": "The person or people you are writing for. Knowing your audience shapes tone, vocabulary and detail.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Body", "d": "The main part of a piece, between the introduction and the conclusion, where the point is developed.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Citation", "d": "The reference that tells a reader where a fact, idea or quote came from.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Clause", "d": "A group of words containing a subject and a verb. An independent clause can stand alone; a dependent clause cannot.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Conclusion", "d": "The closing section that ties the piece together and states what it means. It should not introduce new arguments.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Conflict", "d": "The obstacle pushing against a character's goal. It is the engine of a story.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Conciseness", "d": "Using the fewest words necessary to say something clearly. Cut filler and repetition.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Dialogue", "d": "The spoken words of characters in a story, shown in quotation marks and used to reveal character and advance the plot.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Draft", "d": "A version of a piece. The first draft is the rough initial version; later drafts are improved versions.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Editing", "d": "Improving the writing at the sentence and paragraph level: word choice, flow, repetition and clarity.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Hook", "d": "The opening line or lines that catch a reader's attention and make them want to continue.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Introduction", "d": "The opening section that states what the piece is about and gives the reader a reason to read on.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Metaphor", "d": "Describing one thing as another to make a comparison without using \"like\" or \"as\": \"time is a thief.\"", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Narration", "d": "The voice telling a story, and the perspective from which it is told (first, second or third person).", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Paraphrase", "d": "Restating an idea from a source in your own words, still giving credit to the source.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Pitch", "d": "A short proposal sent to a publication or editor to sell an idea before you write it.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Plagiarism", "d": "Presenting someone else's words, ideas or work as your own without credit.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Plot", "d": "The sequence of events in a story and how they connect to create change.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Proofreading", "d": "The final pass that catches typos, punctuation errors and inconsistencies. It comes after editing.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Revision", "d": "The stage of improving the big picture of a piece — structure, argument and clarity — before sentence-level editing.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Tone", "d": "The attitude the writing conveys: formal, warm, urgent, playful. Tone changes per piece.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Topic sentence", "d": "The sentence that states the main idea of a paragraph.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Transition", "d": "A word or phrase that connects ideas and shows how they relate: \"however\", \"as a result\", \"in practice\".", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Thesis", "d": "The central claim of an essay or paper that the rest of the work defends.", "u": "/glossary/", "s": "Glossary"}, {"t": "Glossary: Voice", "d": "The writer's consistent, recognisable way of writing, independent of the tone of any one piece.", "u": "/glossary/", "s": "Glossary"}];
